<script>
(function(){const date=document.getElementById('test_date');const b=document.getElementById('body_test_date');const s=document.getElementById('seat_test_date');function sync(){if(date.value){if(!b.value)b.value=date.value;if(!s.value)s.value=date.value;document.getElementById('bodyLogDate').value=fmt(date.value);document.getElementById('seatLogDate').value=fmt(date.value)}}function fmt(v){const p=v.split('-');return p.length===3?p[2]+'/'+p[1]+'/'+p[0]:v}date.addEventListener('change',sync);['body_final_pressure','seat_final_pressure'].forEach(n=>document.querySelector('[name='+n+']').addEventListener('input',function(){document.getElementById(n==='body_final_pressure'?'bodyFinalLog':'seatFinalLog').value=this.value}));function preview(input,id){input.addEventListener('change',function(){const f=this.files[0],box=document.getElementById(id);if(!f){box.textContent='Preview';return}const img=document.createElement('img');img.src=URL.createObjectURL(f);box.innerHTML='';box.appendChild(img)})}preview(document.querySelector('[name=tested_signature]'),'p1');preview(document.querySelector('[name=witnessed_signature]'),'p2');preview(document.querySelector('[name=stamp_image]'),'p3');
const addBtn=document.getElementById('addWithholding');const logBody=document.getElementById('pressureLogBody');function refreshAddButton(){addBtn.disabled=false;addBtn.title='Add next test withholding stage';addBtn.setAttribute('aria-label','Add next test withholding stage')}addBtn.addEventListener('click',function(){const rows=[...logBody.querySelectorAll('.withholding-row')];const current=Math.max(...rows.map(r=>Number(r.dataset.stage)||0),0);const next=current+10;const tr=document.createElement('tr');tr.className='withholding-row';tr.dataset.stage=next;tr.innerHTML='<td><input name="description[]" value="TEST WITHHOLDING TIME @ '+next+'%"></td><td><input name="body_log[]" value="15 MINS"></td><td><input name="seat_log[]" value="15 MINS"></td><td><input name="remarks[]"></td>';const totalRow=[...logBody.children].find(r=>{const i=r.querySelector('input[name="description[]"]');return i&&i.value==='TOTAL TEST TIME:'});logBody.insertBefore(tr,totalRow||null);refreshAddButton()});refreshAddButton();})();
</script></body></html>
